"""Test 11: the analysis t11-rule.md fixes, from the counts of jobs 1 to 3 on ibm_fez qubit 143, and every item the rule
reports beside the verdicts. Written, with every choice below, before any job's counts existed.

Job 1 (test 7's design on day 2). The public repository's own code at the v0.8.0 release (commit 09bdebd, unpacked
unedited into src-09bdebd; the package imported from its src/, its test helpers from its tests/):
  - _reuse_runs.t7_ramsey_xy(doc, seeds): test 7's S and P fits, held-out errors, bootstrap of 2,000 draws and verdict
    by the package's manacitra.wait.ramsey_xy_fit with the rule's thresholds, and the items beside the verdict as
    test 7's analysis fixed them (the telegraph model T, the weight, the beat nodes, the envelope, the detuning, the
    periodograms and the four-tone check, the readout, the scheduled waits, the published values). Run on day 1's
    record before the run, it reproduces day 1's archived verdict, held-out errors, delta and b exactly.
  - _reuse_runs.t7_readings(doc, analysis, seeds) and t7_span_readings(doc, spans), t7_spans(spans): amendment A26's
    reading by execution span (the upper line's implied weight, P held at the day's fit, at the positions whose lever
    is at least 0.35; its inverse-variance mean per span; the nearest three positions passing the lever on each side
    of each boundary; the copies check split by same-span and cross-span pairs).
  - The seeds, by the author's ruling before the go (rulings-t11.md, item 1): S starts 7302, P random starts 7303,
    bootstrap 11304, T random starts 7305, periodogram noise 7306.
  - The verdict word: CONFIRMED ON DAY 2 if the package's verdict is TWO FIXED FREQUENCIES, else NOT CONFIRMED ON DAY 2;
    delta and b with their intervals beside day 1's (read from day 1's archived record in the same release).
  - The weight changes across job 1's span boundaries (the counts of the run): by the author's ruling (item 3), the
    plain mean of the three positions after minus the plain mean of the three before; a change of 0.10 or more counts.
Jobs 2 and 3 (the monitor): monitor_t11.analyse_job, per job, with R0 = A exp(-5.6 / tau') from job 1's P fit if job 1
is CONFIRMED ON DAY 2 (else test 7's 0.466), the branches exchanged if job 1's b is above one half; the median phase by
the author's ruling (item 2). The pooled verdicts; the gap between the jobs; the boundary tables.
The counts of the run, each beside the model's number from the rule's bets section. Readout from the in-job readout
circuits beside the published value at the stamp in force at submission.

Usage: python -B analyse_t11.py [--dir DIR] [--out fits-t11.json]
Never prints account details."""
from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import argparse  # noqa: E402
import csv  # noqa: E402
import hashlib  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import time  # noqa: E402
from datetime import datetime  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402

HERE = Path(__file__).resolve().parent
SRC = HERE / "src-09bdebd"
sys.path.insert(0, str(SRC / "src"))
sys.path.insert(0, str(SRC / "tests"))
sys.path.insert(0, str(HERE))
import manacitra  # noqa: E402
from manacitra import archive as ar  # noqa: E402
import _reuse_runs as reuse  # noqa: E402
import monitor_t11 as MON  # noqa: E402

SEEDS = {"S_starts": 7302, "P_random_starts": 7303, "bootstrap": 11304, "T_random_starts": 7305, "periodogram_noise": 7306}
FIT_COMMIT = "09bdebdb0d9be9b4e582ff598869e7d156237aa5"
W_CHANGE = 0.10
DAY1 = {"delta_ci90_kHz": [44.7, 44.9], "b_ci90": [0.333, 0.377], "weight_per_span_A26": [0.457, 0.315, 0.274],
        "copies_same_span": [34.9, 43], "copies_cross_span": [836.8, 85]}
MODEL = {"phase_switch_at_the_four_boundaries": {"p_at_least_one": 0.008, "interval": [0.001, 0.026], "predictive_count": 0},
         "phase_switch_within_spans_in_about_186_qubit_seconds": {"p_at_least_one": 0.002},
         "weight_change_0p10_across_the_two_boundaries_of_a_shuffled_job": {"p_every_eligible_qubit": 0.52, "interval_every_eligible": [0.35, 0.69],
                                                                            "p_three_span_check_qubits": 0.91, "interval_three": [0.69, 0.99]},
         "phase_change_across_the_gap_between_the_monitor_jobs": {"p": "about 1 in 60"},
         "weight_switch_within_a_span_jobs_2_3": "the model has no within-span weight channel; a count here is one the model did not predict",
         "floor_note": "the model's file puts the monitor's floor at 8.5 kHz from the 0.3 rad term alone; the bets are read at the record's own floor, about 23 kHz on 143"}


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def load(d, name):
    p = d / name
    return json.loads(p.read_text()) if p.exists() else None


def ones_of(cts):
    return sum(v for k, v in cts.items() if k[-1] == "1")


def stamps_rows(d):
    p = d / "stamps-t11.csv"
    return list(csv.DictReader(p.open())) if p.exists() else []


def job_rows(rows, job):
    """The calibration record's rows for one job, from its build to its fetch, with the submission row's kind written as
    test 7's record wrote it ("submission ..."), which the repository's reader looks for."""
    out = []
    for r in rows:
        k = r["kind"]
        if k.startswith(f"job {job} "):
            r = dict(r)
            r["kind"] = k[len(f"job {job} "):]
            out.append(r)
    return out


def spans_of(rec):
    ex = rec.get("execution_metadata") or {}
    return ex.get("execution_spans") or []


def ts(s):
    return datetime.fromisoformat(s)


def readout(rec, labels_key="circuit"):
    out = {}
    for k in ("P10", "P01"):
        xs = [(ones_of(c), n) for lab, c, n in zip(rec["labels"], rec["counts"], rec["shots"]) if lab[labels_key] == k]
        o, n = sum(x[0] for x in xs), sum(x[1] for x in xs)
        p1 = o / n
        out[k] = {"P1": p1, "se": math.sqrt(p1 * (1 - p1) / n), "n": n, "per_circuit": [x[0] / x[1] for x in xs]}
    p10, p01 = out["P10"]["P1"], 1 - out["P01"]["P1"]
    return {"P1_given_0": p10, "P0_given_1": p01, "e": (p10 + p01) / 2, "circuits": out}


def published_at_submission(d, job):
    sub = load(d, f"submit-t11-job{job}.json")
    if not sub:
        return None
    r = sub.get("stamp_row_at_submission") or {}
    keys = ("stamp_utc", "q143_readout_error", "q143_prob_meas1_prep0", "q143_prob_meas0_prep1", "q143_T1_us", "q143_T2_us")
    return {k: r.get(k) for k in keys}


# --------------------------------------------------------------------------- job 1
def analyse_job1(d, rec):
    rows = job_rows(stamps_rows(d), 1)
    doc = {"labels": rec["labels"], "counts": rec["counts"], "shots": rec["shots"], "timestamps": rec.get("timestamps"),
           "calibration_record": {"stamps": rows}}
    analysis, boot = reuse.t7_ramsey_xy(doc, SEEDS)
    readings = reuse.t7_readings(doc, analysis, SEEDS)
    doc["archived"] = {"readings_after_the_data": readings}
    sp = spans_of(rec)
    out = {"code": {"release": "v0.8.0", "commit": FIT_COMMIT, "manacitra_version_string": manacitra.__version__,
                    "functions": "_reuse_runs.t7_ramsey_xy, t7_readings, t7_spans, t7_span_readings; manacitra.wait.ramsey_xy_fit"},
           "seeds": SEEDS, "package_verdict": analysis["verdict"],
           "verdict": "CONFIRMED ON DAY 2" if analysis["verdict"] == "TWO FIXED FREQUENCIES" else "NOT CONFIRMED ON DAY 2",
           "analysis": analysis, "readings_after_the_data": readings, "bootstrap_meta": boot.get("meta")}
    dec = analysis["deciding"]
    P = analysis["fits"]["P"]["params"]
    out["beside_day1"] = {"delta_kHz_day2": P["delta_MHz"] * 1e3, "delta_ci90_kHz_day2": dec["delta_ci90_kHz"], "delta_ci90_kHz_day1": DAY1["delta_ci90_kHz"],
                          "b_day2": P["b"], "b_ci90_day2": dec["b_ci90"], "b_ci90_day1": DAY1["b_ci90"],
                          "held_out_error_S_day2": dec["held_out_error_S"], "held_out_error_P_day2": dec["held_out_error_P"]}
    try:
        d1 = ar.load("ibm_fez/t7-ramsey-xy.json")["archived"]["analysis"]
        out["beside_day1"]["day1_archived"] = {"verdict": d1["verdict"], "deciding": d1["deciding"], "fits": d1["fits"]}
    except Exception as e:
        out["beside_day1"]["day1_archived"] = {"error": type(e).__name__}
    if sp:
        spans = {"spans": sp, "n_positions": len(rec["labels"])}
        out["spans_derived"] = reuse.t7_spans(spans)
        sr = reuse.t7_span_readings(doc, spans)
        out["span_readings_A26"] = sr
        changes = {}
        for name, b in sr["span_boundaries"].items():
            bw = [x["weight"] for x in b["before"]]
            aw = [x["weight"] for x in b["after"]]
            if len(bw) == 3 and len(aw) == 3:
                ch = float(np.mean(aw) - np.mean(bw))
                changes[name] = {"between_positions": b["between_positions"], "before": b["before"], "after": b["after"], "mean_before": float(np.mean(bw)),
                                 "mean_after": float(np.mean(aw)), "change": ch, "at_least_0p10": abs(ch) >= W_CHANGE}
            else:
                changes[name] = {"between_positions": b["between_positions"], "before": b["before"], "after": b["after"], "note": "fewer than three positions passing the lever on a side"}
        out["weight_changes_across_boundaries"] = {"rule": "the author's ruling: the plain mean of the three after minus the plain mean of the three before; 0.10 or more counts",
                                                   "boundaries": changes, "n_at_least_0p10": sum(1 for c in changes.values() if c.get("at_least_0p10")),
                                                   "n_boundaries": len(changes)}
    else:
        out["spans_derived"] = None
        out["span_readings_A26"] = {"note": "no execution metadata saved with the counts; to be retrieved again before analysis"}
    out["R0_for_the_monitor"] = P["A"] * math.exp(-MON.WAIT_US / P["tau_prime_us"])
    out["antiphase_wait_from_day2_split_us"] = 1.0 / (4 * P["delta_MHz"])
    out["readout"] = {"measured": readout(rec), "published_at_submission": published_at_submission(d, 1)}
    return out


# --------------------------------------------------------------------------- jobs 2 and 3
def monitor_spans(rec):
    return [{"span": s["span"], "positions": s["positions"], "start": ts(s["start_utc"]), "stop": ts(s["stop_utc"]), "duration_s": s["duration_s"]}
            for s in spans_of(rec)]


def execution_record(rec):
    sp = spans_of(rec)
    order = sorted(sp, key=lambda s: s["start_utc"])
    runs = lambda idx: reuse._runs(idx)
    return {"n_spans": len(sp), "spans": [{"span": s["span"], "start_utc": s["start_utc"], "stop_utc": s["stop_utc"], "duration_s": s["duration_s"],
                                           "position_runs": runs(s["positions"]), "n_positions": len(s["positions"]),
                                           "every_position_all_its_shots": all(v == rec["shots"][int(p)] for p, v in s["shots_per_position"].items())} for s in order],
            "gaps_s": [(ts(b["start_utc"]) - ts(a["stop_utc"])).total_seconds() for a, b in zip(order, order[1:])]}


def analyse_monitor(rec, R0, exchange, confirmed):
    ones = [ones_of(c) for c in rec["counts"]]
    r = MON.analyse_job(ones, rec["labels"], monitor_spans(rec), R0, exchange=exchange, job1_confirmed=confirmed)
    r["execution_record"] = execution_record(rec)
    r["readout"] = readout(rec)
    r["scheduled_wait"] = rec.get("waits")
    r["series"] = {"k": [x["k"] for x in r["repeats"]], "theta": [x["theta"] for x in r["repeats"]], "r": [x["r"] for x in r["repeats"]],
                   "w": [x["w"] for x in r["repeats"]], "s": [x["s"] for x in r["repeats"]], "se_w": [x["se_w"] for x in r["repeats"]],
                   "span": [x["span"] for x in r["repeats"]], "straddles": [x["straddles"] for x in r["repeats"]]}
    return r
